-- Diners, Drive-Ins, and Dives Database --
-- Kristina Gavin Bigsby (2024) --
-- Data collected from Kaggle (https://www.kaggle.com/datasets/keeganwilleford/triple-d-eateries-with-address-and-yelp-rating),
-- Food Network (https://www.foodnetwork.com/shows/diners-drive-ins-and-dives), and US Census Bureau (https://data.census.gov/)

-- DROP TABLES --
DROP TABLE APPEARANCE;
DROP TABLE EPISODE;
DROP TABLE RESTAURANT;
DROP TABLE LOCALE;

-- CREATE TABLES --
CREATE TABLE LOCALE (
    LocaleID CHAR(6) NOT NULL,
    City VARCHAR2(100) NOT NULL,
    State CHAR(2) NOT NULL,
    Population NUMBER(*,0) NOT NULL,
    Density NUMBER(*,1) NOT NULL,
    Poverty NUMBER(*,2) NOT NULL CHECK (Poverty BETWEEN 0 AND 1),
    Income NUMBER(*,0) NOT NULL,
    Housing NUMBER(*,0) NOT NULL,
    CONSTRAINT LOCALE_PK PRIMARY KEY (LocaleID)
);

CREATE TABLE RESTAURANT (
    RestaurantID CHAR(6) NOT NULL,
    Restaurant VARCHAR2(100) NOT NULL,
    Cuisine VARCHAR2(50) NOT NULL,
    Rating NUMBER(*,1) CHECK (Rating BETWEEN 0 AND 5),
    LocaleID CHAR(6) NOT NULL,
    Website VARCHAR2(150),
    CONSTRAINT RESTAURANT_PK PRIMARY KEY (RestaurantID),
    CONSTRAINT RESTAURANT_FK FOREIGN KEY (LocaleID) REFERENCES LOCALE (LocaleID)
);

CREATE TABLE EPISODE (
    EpisodeID CHAR(6) NOT NULL,
    Season NUMBER(2,0) NOT NULL,
    Episode NUMBER(2,0) NOT NULL,
    Title VARCHAR2(100) NOT NULL,
    AirDate DATE NOT NULL,
    CONSTRAINT EPISODE_PK PRIMARY KEY (EpisodeID)
);

CREATE TABLE APPEARANCE (
    EpisodeID CHAR(6) NOT NULL,
    RestaurantID CHAR(6) NOT NULL,
    CONSTRAINT APPEARANCE_PK PRIMARY KEY (EpisodeID, RestaurantID),
    CONSTRAINT APPEARANCE_FK1 FOREIGN KEY (EpisodeID) REFERENCES EPISODE (EpisodeID),
    CONSTRAINT APPEARANCE_FK2 FOREIGN KEY (RestaurantID) REFERENCES RESTAURANT (RestaurantID)
);

